// Package adopt writes a starter registry from what discovery found: the
// "adopt your mess" path. It records the machine as it is, so the first real
// run after it is clean and every later change shows up as a finding.
package adopt

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode"

	"gopkg.in/yaml.v3"

	"github.com/kd-011/unlisted/internal/check"
	"github.com/kd-011/unlisted/internal/discover"
)

// Result is the generated file plus what it contained, for the summary line.
type Result struct {
	YAML     string
	Hosts    int
	Ports    int
	AuthNone int      // services written with auth: none because none was detected
	Ignored  []string // hosts written with ignore: true, and why
}

type entry struct {
	name, host, url, auth, note string
	port                        int
	ignore                      bool
}

const header = `# unlisted registry: what you say you run.
#
# Generated by "unlisted init" from what this machine exposes right now.
# Edit it: give things proper names, delete what should not exist, and set
# auth honestly. "auth: none" below only means no auth was detected at the
# time, not that none exists. Fields: name, host, port, url, auth
# (none | proxy | app | cloudflare-access), owner, note, ignore.
`

// Build creates the registry text for a snapshot.
func Build(snap discover.Snapshot) Result {
	var res Result
	var entries []entry
	usedPorts := map[int]bool{}
	names := map[string]int{}

	unique := func(n string) string {
		names[strings.ToLower(n)]++
		if c := names[strings.ToLower(n)]; c > 1 {
			return fmt.Sprintf("%s %d", n, c)
		}
		return n
	}

	procLoaded := snap.Loaded("proc")
	listening := map[int]bool{}
	for _, l := range snap.Listeners {
		listening[l.Port] = true
	}

	for _, s := range check.MergeSites(snap.Exposures) {
		e := entry{host: s.Host, name: unique(titleFromHost(s.Host))}
		if !s.Origin.IsZero() && s.Origin.Port != 0 && s.Origin.Scheme != "unix" {
			if s.Origin.Local {
				e.port = s.Origin.Port
				usedPorts[e.port] = true
			} else {
				scheme := s.Origin.Scheme
				if scheme == "" || scheme == "tcp" {
					scheme = "http"
				}
				e.url = fmt.Sprintf("%s://%s", scheme, s.Origin.Addr())
			}
		}
		switch {
		case s.Auth && s.AuthBy == "originRequest.access":
			e.auth = "cloudflare-access"
			e.note = "auth detected: " + s.AuthBy
		case s.Auth:
			e.auth = "proxy"
			e.note = "auth detected: " + s.AuthBy
		default:
			e.auth = "none"
			res.AuthNone++
		}
		// A rule that points at a dead port would be a DEAD finding the moment
		// the registry is read back. Adopt records it but silences it, and says
		// so out loud, so the first run after init is clean without hiding it.
		if procLoaded && e.port != 0 && !listening[e.port] {
			e.ignore = true
			e.note = fmt.Sprintf("nothing was listening on :%d when scanned; fix or delete", e.port)
			res.Ignored = append(res.Ignored, fmt.Sprintf("%s (nothing listening on :%d)", s.Host, e.port))
		}
		entries = append(entries, e)
		res.Hosts++
	}

	covered := usedPorts
	var listeners []discover.Listener
	for _, l := range snap.Listeners {
		if l.Public && !covered[l.Port] && !ownProxy(l, snap) {
			listeners = append(listeners, l)
		}
	}
	sort.Slice(listeners, func(i, j int) bool { return listeners[i].Port < listeners[j].Port })
	for _, l := range listeners {
		label := l.Name()
		if label == "" {
			label = "port " + strconv.Itoa(l.Port)
		}
		e := entry{name: unique(label), port: l.Port, auth: "none", note: "found listening on " + l.Addr}
		if l.Container != "" {
			e.note = "docker container " + l.Container
		}
		res.AuthNone++
		entries = append(entries, e)
		res.Ports++
	}

	var b strings.Builder
	b.WriteString(header)
	b.WriteString("\nservices:\n")
	for _, e := range entries {
		b.WriteString("  - name: " + scalar(e.name) + "\n")
		if e.host != "" {
			b.WriteString("    host: " + scalar(e.host) + "\n")
		}
		if e.port != 0 {
			b.WriteString("    port: " + strconv.Itoa(e.port) + "\n")
		}
		if e.url != "" {
			b.WriteString("    url: " + scalar(e.url) + "\n")
		}
		b.WriteString("    auth: " + e.auth + "\n")
		if e.note != "" {
			b.WriteString("    note: " + scalar(e.note) + "\n")
		}
		if e.ignore {
			b.WriteString("    ignore: true\n")
		}
	}
	if len(entries) == 0 {
		b.WriteString("  []\n")
	}
	res.YAML = b.String()
	return res
}

func ownProxy(l discover.Listener, snap discover.Snapshot) bool {
	hay := strings.ToLower(l.Process + " " + l.Container + " " + l.Image + " " + l.Unit)
	for _, n := range []string{"caddy", "nginx", "cloudflared"} {
		if !strings.Contains(hay, n) {
			continue
		}
		for _, st := range snap.Sources {
			if st.Name == n && st.State == "ok" && st.Count > 0 {
				return true
			}
		}
	}
	return false
}

// titleFromHost turns jellyfin.example.com into Jellyfin.
func titleFromHost(h string) string {
	wild := strings.HasPrefix(h, "*.")
	h = strings.TrimPrefix(h, "*.")
	label := h
	if i := strings.IndexByte(h, '.'); i > 0 {
		label = h[:i]
	}
	r := []rune(strings.NewReplacer("-", " ", "_", " ").Replace(label))
	if len(r) == 0 {
		return h
	}
	r[0] = unicode.ToUpper(r[0])
	name := string(r)
	if wild {
		name += " (wildcard)"
	}
	return name
}

// scalar quotes a string only when YAML needs it.
func scalar(s string) string {
	b, err := yaml.Marshal(s)
	if err != nil {
		return strconv.Quote(s)
	}
	return strings.TrimRight(string(b), "\n")
}
